class Inventory:
    def __init__(self, stock):
        self.stock = dict(stock)
        self.requests = {}

    def _aggregate(self, lines):
        total = {}
        for sku, n in lines:
            if n <= 0:
                return None
            total[sku] = total.get(sku, 0) + n
        return total

    def reserve(self, request_id, lines):
        total = self._aggregate(lines)
        if total is None:
            return False
        if request_id in self.requests:
            return self.requests[request_id] == total
        if any(self.stock.get(sku, 0) < n for sku, n in total.items()):
            return False
        for sku, n in total.items():
            self.stock[sku] -= n
        self.requests[request_id] = total
        return True

    def cancel(self, request_id):
        lines = self.requests.pop(request_id, None)
        if lines is None:
            return False
        for sku, n in lines.items():
            self.stock[sku] = self.stock.get(sku, 0) + n
        return True

    def snapshot(self):
        return dict(self.stock)

